package harmonised.pmmo.events.impl;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import harmonised.pmmo.api.APIUtils;
import harmonised.pmmo.api.enums.EventType;
import harmonised.pmmo.api.enums.ReqType;
import harmonised.pmmo.config.Config;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.party.PartyUtils;
import harmonised.pmmo.features.veinmining.VeinMiningLogic;
import harmonised.pmmo.storage.ChunkDataHandler;
import harmonised.pmmo.storage.ChunkDataProvider;
import harmonised.pmmo.storage.IChunkData;
import harmonised.pmmo.util.Messenger;
import harmonised.pmmo.util.Reference;
import harmonised.pmmo.util.RegistryUtil;
import harmonised.pmmo.util.TagUtils;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.CropBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraftforge.event.level.BlockEvent.BreakEvent;

public class BreakHandler {

	@SuppressWarnings("resource")
	public static void handle(BreakEvent event) {
		Core core = Core.get(event.getPlayer().level());
		boolean serverSide = !event.getPlayer().level().isClientSide;
		if (!core.isActionPermitted(ReqType.BREAK, event.getPos(), event.getPlayer())) {
			event.setCanceled(true);
			Messenger.sendDenialMsg(ReqType.BREAK, event.getPlayer(), event.getState().getBlock().getName());
			return;
		}
		CompoundTag eventHookOutput = new CompoundTag();
		if (serverSide){
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(EventType.BLOCK_BREAK, event, new CompoundTag());
			if (eventHookOutput.getBoolean(APIUtils.IS_CANCELLED)) {
				event.setCanceled(true);
				return;
			}
		}
		//Process perks on both sides. note that only server-side perks will affect xp outputs.
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(EventType.BLOCK_BREAK, event.getPlayer(), eventHookOutput));
		if (serverSide) {
			Map<String, Long> xpAward = calculateXpAward(core, event, perkOutput);
			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.getPlayer());
			core.awardXP(partyMembersInRange, xpAward);
			//update ChunkData to remove the block from the placed map
			//if a cascading breaking crop block, add the breaker value.
			LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
			chunk.getCapability(ChunkDataProvider.CHUNK_CAP).ifPresent(cap -> {
				cap.delPos(event.getPos());
				if (event.getLevel().getBlockState(event.getPos()).is(Reference.CASCADING_BREAKABLES))
					cap.setBreaker(event.getPos(), event.getPlayer().getUUID());
			});;
			chunk.setUnsaved(true);
		}
		//==============Process Vein Miner Logic==================
		if (core.getMarkedPos(event.getPlayer().getUUID()).equals(event.getPos())) {
			BlockState block = event.getLevel().getBlockState(event.getPos());
			Item tool = event.getPlayer().getMainHandItem().getItem();
			if (!Config.VEIN_BLACKLIST.get().contains(RegistryUtil.getId(tool).toString())) {
				VeinMiningLogic.applyVein((ServerPlayer) event.getPlayer(), event.getPos());
			}
		}
	}

	private static Map<String, Long> calculateXpAward(Core core, BreakEvent event, CompoundTag dataIn) {
		Map<String, Long> outMap = core.getExperienceAwards(EventType.BLOCK_BREAK, event.getPos(), (Level)event.getLevel(), event.getPlayer(), dataIn); 
		LevelChunk chunk = (LevelChunk) event.getLevel().getChunk(event.getPos());
		IChunkData cap = chunk.getCapability(ChunkDataProvider.CHUNK_CAP).orElseGet(ChunkDataHandler::new);
		if (cap.playerMatchesPos(event.getPlayer(), event.getPos())) {
			//Do not apply self-place penalty to crops
			BlockState cropState = event.getLevel().getBlockState(event.getPos()); 
			if (cropState.getBlock() instanceof CropBlock && ((CropBlock)cropState.getBlock()).isMaxAge(cropState))
				return outMap;
			double xpModifier = Config.REUSE_PENALTY.get();
			if (xpModifier == 0) return new HashMap<>();
			Map<String, Long> modifiedOutMap = new HashMap<>();
			outMap.forEach((k, v) -> modifiedOutMap.put(k, (long)((double)v * xpModifier)));
			return modifiedOutMap;
		}
		return outMap;
	}
}

package harmonised.pmmo.events.impl;

import java.util.Map;

import harmonised.pmmo.config.Config;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.veinmining.VeinMiningLogic;
import harmonised.pmmo.network.Networking;
import harmonised.pmmo.network.clientpackets.CP_ResetXP;
import harmonised.pmmo.network.clientpackets.CP_SyncVein;
import harmonised.pmmo.network.clientpackets.CP_UpdateExperience;
import harmonised.pmmo.network.clientpackets.CP_UpdateLevelCache;
import harmonised.pmmo.network.serverpackets.SP_SetVeinLimit;
import harmonised.pmmo.storage.PmmoSavedData;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent;
import net.minecraftforge.fml.LogicalSide;

public class LoginHandler {

	public static void handle(PlayerLoggedInEvent event) {		
		Player player = event.getEntity();
		Core core = Core.get(player.level());

		if (core.getSide().equals(LogicalSide.SERVER)) {
			//===========UPDATE DATA MIRROR=======================
			Networking.sendToClient(new CP_ResetXP(), (ServerPlayer) player);
			for (Map.Entry<String, Long> skillMap : core.getData().getXpMap(player.getUUID()).entrySet()) {
				Networking.sendToClient(new CP_UpdateExperience(skillMap.getKey(), skillMap.getValue()), (ServerPlayer) player);
			}
			Networking.sendToClient(new CP_UpdateLevelCache(((PmmoSavedData)core.getData()).getLevelCache()), (ServerPlayer) player);
			Networking.sendToClient(new CP_SyncVein(VeinMiningLogic.getCurrentCharge(player)), (ServerPlayer) player);

			//===========EXECUTE FEATURE LOGIC====================
			((PmmoSavedData)core.getData()).awardScheduledXP(player.getUUID());
		}
		else {
			Networking.sendToServer(new SP_SetVeinLimit(Config.VEIN_LIMIT.get()));
		}
	}
}

package harmonised.pmmo.events.impl;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import harmonised.pmmo.api.APIUtils;
import harmonised.pmmo.api.enums.EventType;
import harmonised.pmmo.config.Config;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.core.CoreUtils;
import harmonised.pmmo.features.anticheese.CheeseTracker;
import harmonised.pmmo.features.party.PartyUtils;
import harmonised.pmmo.features.penalties.EffectManager;
import harmonised.pmmo.features.veinmining.VeinMiningLogic;
import harmonised.pmmo.util.TagUtils;
import harmonised.pmmo.util.RegistryUtil;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.TickEvent.PlayerTickEvent;
import net.minecraftforge.fml.LogicalSide;

public class PlayerTickHandler {
	private static final Map<UUID, Integer> airLast = new HashMap<>();
	private static final Map<UUID, Float> healthLast = new HashMap<>();
	private static final Map<UUID, Vec3> moveLast = new HashMap<>();

	public static void handle(PlayerTickEvent event) {
		if (event.phase != TickEvent.Phase.END && event.player.tickCount % 10 != 0) return;

		Player player = event.player;
		Core core = Core.get(event.side);

		//Recharge vein items
		if (player instanceof ServerPlayer) {
			VeinMiningLogic.regenerateVein((ServerPlayer)player);
			//Apply positive and negative effects based on biome and items worn
			EffectManager.applyEffects(core, player);
		}

		if (!airLast.containsKey(player.getUUID()))
			airLast.put(player.getUUID(), player.getAirSupply());
		if (!healthLast.containsKey(player.getUUID()))
			healthLast.put(player.getUUID(), player.getHealth());

		if (player.getAirSupply() != airLast.getOrDefault(player.getUUID(), 0))
			processEvent(EventType.BREATH_CHANGE, core, event);
		float healthDiff = player.getHealth() - healthLast.getOrDefault(player.getUUID(), 0f);
		if (Math.abs(healthDiff) >= 0.01) {
			processEvent(EventType.HEALTH_CHANGE, core, event);
			processEvent(healthDiff > 0 ? EventType.HEALTH_INCREASE : EventType.HEALTH_DECREASE, core, event);
		}
		if (player.isPassenger())
			processEvent(EventType.RIDING, core, event);
		if (!player.getActiveEffects().isEmpty())
			processEvent(EventType.EFFECT, core, event);

		if (player.isUnderWater()) {
			processEvent(EventType.SUBMERGED, core, event);
			Vec3 vec = player.getDeltaMovement();
			if (player.isSprinting())
				processEvent(EventType.SWIM_SPRINTING, core, event); 
			//The value of -0.005 is a constant "sinking" rate that entities have even when
			//standing on blocks underwater. This variable captures the threshold above that
			//so that the Submerged event can actually fire.
			double sinkingRate = 0.01;
			if (vec.y() > sinkingRate)
				processEvent(EventType.SURFACING, core, event);
			else if (vec.y() < -sinkingRate)
				processEvent(EventType.DIVING, core, event);
		}
		else if (player.isInWater())
			processEvent(EventType.SWIMMING, core, event); 
		else if (player.isSprinting())
			processEvent(EventType.SPRINTING, core, event);
		else if (player.isCrouching())
			processEvent(EventType.CROUCH, core, event);

		//update tracker variables
		airLast.put(player.getUUID(), player.getAirSupply());
		healthLast.put(player.getUUID(), player.getHealth());
		moveLast.put(player.getUUID(), player.position());
	}

	private static void processEvent(EventType type, Core core, PlayerTickEvent event) {
		CompoundTag eventHookOutput = new CompoundTag();
		boolean serverSide = core.getSide().equals(LogicalSide.SERVER); 
		if (serverSide){			
			eventHookOutput = core.getEventTriggerRegistry().executeEventListeners(type, event, new CompoundTag());
		}
		CompoundTag perkOutput = TagUtils.mergeTags(eventHookOutput, core.getPerkRegistry().executePerk(type, event.player, eventHookOutput));
		if (serverSide) {
			ResourceLocation source = ResourceLocation.withDefaultNamespace("player");
			final Map<String, Long> xpAward = perkOutput.contains(APIUtils.SERIALIZED_AWARD_MAP) 
					? CoreUtils.deserializeAwardMap(perkOutput.getCompound(APIUtils.SERIALIZED_AWARD_MAP))
					: new HashMap<>();
			switch (type) {
			case BREATH_CHANGE -> {
				int diff = Math.abs(airLast.getOrDefault(event.player.getUUID(), 0) - event.player.getAirSupply());
				Map<String, Double> ratio = Config.BREATH_CHANGE_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * diff * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			case HEALTH_CHANGE -> {
				processHealthChange(Config.HEALTH_CHANGE_XP.get(), core, event.player, xpAward);
			}
			case HEALTH_INCREASE -> {
				processHealthChange(Config.HEALTH_INCREASE_XP.get(), core, event.player, xpAward);
			}
			case HEALTH_DECREASE -> {
				processHealthChange(Config.HEALTH_DECREASE_XP.get(), core, event.player, xpAward);
			}
			case RIDING -> {
				source = RegistryUtil.getId(event.player.getVehicle());
                xpAward.putAll(core.getExperienceAwards(type, event.player.getVehicle(), event.player, perkOutput));
                ;
			}
			case EFFECT -> {
				for (MobEffectInstance mei : event.player.getActiveEffects()) {	
					source = RegistryUtil.getId(mei.getEffect());
                    xpAward.putAll(core.getExperienceAwards(mei, event.player, perkOutput));
				}
			}
			case SPRINTING -> {
				Vec3 vec = event.player.position();
				Vec3 old = moveLast.getOrDefault(event.player.getUUID(), vec);
				double magnitude = Math.sqrt(
						Math.pow(Math.abs(vec.x()-old.x()), 2) +
						Math.pow(Math.abs(vec.y()-old.y()), 2) +
						Math.pow(Math.abs(vec.z()-old.z()), 2));
				Map<String, Double> ratio = Config.SPRINTING_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * magnitude * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			case SUBMERGED -> {
				Map<String, Double> ratio = Config.SUBMERGED_XP.get();
				ratio.keySet().forEach((skill) -> {
					xpAward.put(skill, ratio.getOrDefault(skill, 0d).longValue());
				});
			}
			case SWIMMING -> {
				Vec3 vec = event.player.getDeltaMovement();
				double magnitude = Math.sqrt(Math.pow(vec.x(), 2)+Math.pow(vec.y(), 2)+Math.pow(vec.z(), 2));
				Map<String, Double> ratio = Config.SWIMMING_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * magnitude * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			case DIVING -> {
				Vec3 vec = event.player.getDeltaMovement();
				double magnitude = Math.sqrt(Math.pow(vec.x(), 2)+Math.pow(vec.y(), 2)+Math.pow(vec.z(), 2));
				Map<String, Double> ratio = Config.DIVING_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * magnitude * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			case SURFACING -> {
				Vec3 vec = event.player.getDeltaMovement();
				double magnitude = Math.sqrt(Math.pow(vec.x(), 2)+Math.pow(vec.y(), 2)+Math.pow(vec.z(), 2));
				Map<String, Double> ratio = Config.SURFACING_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * magnitude * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			case SWIM_SPRINTING -> {
				Vec3 vec = event.player.getDeltaMovement();
				double magnitude = Math.sqrt(Math.pow(vec.x(), 2)+Math.pow(vec.y(), 2)+Math.pow(vec.z(), 2));
				Map<String, Double> ratio = Config.SWIM_SPRINTING_XP.get();
				ratio.keySet().forEach((skill) -> {
					Double value = ratio.getOrDefault(skill, 0d) * magnitude * core.getConsolidatedModifierMap(event.player).getOrDefault(skill, 1d);
					xpAward.put(skill, value.longValue());
				});
			}
			default -> {}
			}

			CheeseTracker.applyAntiCheese(type, source, event.player, xpAward);

			List<ServerPlayer> partyMembersInRange = PartyUtils.getPartyMembersInRange((ServerPlayer) event.player);
			core.awardXP(partyMembersInRange, xpAward);	
		}
	}

	private static void processHealthChange(Map<String, Double> ratio, Core core, Player player, Map<String, Long> xpAward) {
		float diff = Math.abs(healthLast.getOrDefault(player.getUUID(), 0f) - player.getHealth());
		ratio.keySet().forEach((skill) -> {
			Double value = ratio.getOrDefault(skill, 0d) * diff * core.getConsolidatedModifierMap(player).getOrDefault(skill, 1d);
			xpAward.put(skill, value.longValue());
		});
	}
}

package harmonised.pmmo.features.veinmining;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

//import harmonised.pmmo.compat.curios.CurioCompat;
import harmonised.pmmo.api.enums.ReqType;
import harmonised.pmmo.compat.curios.CurioCompat;
import harmonised.pmmo.config.Config;
import harmonised.pmmo.config.codecs.VeinData;
import harmonised.pmmo.core.Core;
import harmonised.pmmo.features.veinmining.VeinShapeData.ShapeType;
import harmonised.pmmo.features.veinmining.capability.VeinProvider;
import harmonised.pmmo.network.Networking;
import harmonised.pmmo.network.clientpackets.CP_SyncVein;
import harmonised.pmmo.util.MsLoggy;
import harmonised.pmmo.util.RegistryUtil;
import harmonised.pmmo.util.MsLoggy.LOG_CODE;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;

public class VeinMiningLogic {
	public static final String VEIN_DATA = "vein_data";
	public static final String CURRENT_CHARGE = "vein_charge";
	public static final Map<UUID, Integer> maxBlocksPerPlayer = new HashMap<>();
	public static final Map<UUID, ShapeType> shapePerPlayer = new HashMap<>();

	/**This executes the actual break logic.  This should only be called
	 * on the server.
	 * 
	 * @param player
	 * @param pos
	 */
	public static void applyVein(ServerPlayer player, BlockPos pos) {
		if (!Config.VEIN_ENABLED.get()) return;
		ServerLevel level = player.serverLevel();
		Block block = level.getBlockState(pos).getBlock();
		int cost = Core.get(level).getBlockConsume(block);
		if (cost <= 0) return; 
		int charge = getCurrentCharge(player);
		int consumed = 0;			
		int maxBlocks = Math.min(charge/cost, maxBlocksPerPlayer.computeIfAbsent(player.getUUID(), id -> 64));
		ShapeType mode = shapePerPlayer.computeIfAbsent(player.getUUID(), id -> ShapeType.AOE);
		VeinShapeData veinData = new VeinShapeData(level, pos, maxBlocks, mode, player.getDirection());
		for (BlockPos veinable : veinData.getVein()) {
			consumed += cost;
			player.gameMode.destroyAndAck(veinable, 1, "Vein Break");
		}
		MsLoggy.DEBUG.log(LOG_CODE.FEATURE, "Vein Consumed: "+consumed+" charge");
		applyChargeCost(player, consumed, charge);
	}

	public static void regenerateVein(ServerPlayer player) {
		if (!Config.VEIN_ENABLED.get()) return;
		Inventory inv = player.getInventory();	
		List<ItemStack> items = new ArrayList<>();
		items.addAll(inv.armor);
		items.add(inv.getSelected());
		items.addAll(inv.offhand);
		//========== CURIOS ==============
		if (CurioCompat.hasCurio) {
			items = new ArrayList<>(items);
			items.addAll(CurioCompat.getItems(player));
		}
		//================================
		Core core = Core.get(player.level());
		double currentCharge = getCurrentCharge(player);
		int chargeCap = Config.BASE_CHARGE_CAP.get();
		double chargeRate = Config.BASE_CHARGE_RATE.get();
		for (ItemStack stack : items) {
			VeinData data;
			if (!core.isActionPermitted(ReqType.WEAR, stack, player)) continue;
			if ((data = core.getLoader().ITEM_LOADER.getData(RegistryUtil.getId(stack)).veinData()).chargeRate.isPresent()) {
				chargeCap += data.chargeCap.orElse(0);
				chargeRate += data.chargeRate.orElse(0d);
			}
		}
		if (chargeRate == 0 || chargeCap == 0 || currentCharge >= chargeCap) 
			return;

		final int fCap = chargeCap;
		final double fRate = chargeRate * Config.VEIN_CHARGE_MODIFIER.get();
		if ((currentCharge + fRate) >= fCap) {
			player.getCapability(VeinProvider.VEIN_CAP).ifPresent(vein -> {
				vein.setCharge(fCap);
				MsLoggy.DEBUG.log(MsLoggy.LOG_CODE.FEATURE, "Regen at Cap: "+fCap);
				Networking.sendToClient(new CP_SyncVein(fCap), player);
			});

		}
		else {
			player.getCapability(VeinProvider.VEIN_CAP).ifPresent(vein -> {
				vein.setCharge(vein.getCharge() + fRate);
				MsLoggy.DEBUG.log(MsLoggy.LOG_CODE.FEATURE, "Regen: "+(vein.getCharge()+fRate));
				Networking.sendToClient(new CP_SyncVein(vein.getCharge() + fRate),player);
			});	

		}
	}

	//=========================UTILITY METHODS=============================

	public static int getCurrentCharge(Player player) {
		return player.getCapability(VeinProvider.VEIN_CAP).map(vein -> (int)vein.getCharge()).orElse(0); 
	}

	@SuppressWarnings("resource")
	public static int getMaxChargeFromAllItems(Player player) {
		Inventory inv = player.getInventory();		
		List<ItemStack> items = List.of(inv.getItem(36), inv.getItem(37), inv.getItem(38), inv.getItem(39), player.getMainHandItem(), player.getOffhandItem());
		//========== CURIOS ==============
		if (CurioCompat.hasCurio) {
			items = new ArrayList<>(items);
			items.addAll(CurioCompat.getItems(player));
		}
		//================================
		int totalCapacity = Config.BASE_CHARGE_CAP.get();
		for (ItemStack stack : items) {
			if (!Core.get(player.level()).isActionPermitted(ReqType.WEAR, stack, player)) continue;
			totalCapacity += Core.get(player.level()).getLoader().ITEM_LOADER.getData(RegistryUtil.getId(stack)).veinData().chargeCap.orElse(0);
		}
		MsLoggy.DEBUG.log(LOG_CODE.FEATURE, "Vein Capacity: "+totalCapacity);
		return totalCapacity; 
	}

	private static void applyChargeCost(ServerPlayer player, int cost, double currentCharge) {
		player.getCapability(VeinProvider.VEIN_CAP).ifPresent(vein -> vein.setCharge(currentCharge-cost));
		Networking.sendToClient(new CP_SyncVein(currentCharge-cost), player);
	}
}

package harmonised.pmmo.features.veinmining;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;

public class VeinShapeData {
	public static enum ShapeType {AOE, TUNNEL, BIG_TUNNEL}

	private Level level;
	private BlockPos center;
	private int maxBlocks;
	private final Map<BlockPos, Node> map = new HashMap<>();
	private final ShapeType mode;
	private final Direction face;

	public VeinShapeData(Level level, BlockPos center, int maxBlocks, ShapeType mode, Direction playerFacing) {
		this.level = level;
		this.center = center;
		this.maxBlocks = maxBlocks;
		this.mode = mode;
		this.face = playerFacing;
		map.put(center, new Node(0, false, false));
	}

	public Set<BlockPos> getVein() {
		Block block = level.getBlockState(center).getBlock();
		return switch (mode) {
		//STANDARD TRACING SHAPE
		case AOE -> {
			int ring = 0;
			while (maxBlocks > 0) {
				addNodesForRing(ring, block);
				ring++;
			}
			map.remove(center);
			yield map.keySet();
		}
		//TWO-HIGH TUNNEL
		case TUNNEL -> {
			final BlockState centerState = level.getBlockState(center);
			BlockPos lastPos = center;
			while (maxBlocks > 0 && !lastPos.equals(BlockPos.ZERO)) {
				lastPos = stepShape(lastPos, centerState, false);
			}
			map.remove(center);
			yield map.keySet();
		}
		case BIG_TUNNEL -> {
			final BlockState centerState = level.getBlockState(center);
			BlockPos lastPos = center;
			while (maxBlocks > 0 && !lastPos.equals(BlockPos.ZERO)) {
				lastPos = stepShape(lastPos, centerState, true);
			}
			map.remove(center);
			yield map.keySet();
		}
		default -> map.keySet();};

	}

	private void addNodesForRing(int ring, Block block) {
		Map<BlockPos, Node> ringMap = new HashMap<>();
		map.forEach((pos, node) -> {
			if (node.ring() == ring && !node.scanned() && !node.isTerminal()) 
				ringMap.put(pos, node);
		});
		if (ringMap.isEmpty()) {
			maxBlocks = 0;
			return;
		}
		ringMap.forEach((pos, node) -> {
			map.put(pos, node.setScanned());
			Map<BlockPos, Node> newRingMap = new HashMap<>();
			outer:
			for (int x = -1; x <= 1; x++) {
				for (int y = -1; y <= 1; y++) {
					for (int z = -1; z <= 1; z++) {
						if (maxBlocks <= 0)
							break outer;
						BlockPos currentPos = pos.offset(x, y, z);
						if (map.containsKey(currentPos)) continue; 
						if (level.getBlockState(currentPos).getBlock().equals(block)) {
							newRingMap.put(currentPos, new Node(ring+1, false, false));
							maxBlocks--;
						}
					}
				}
			}
			if (newRingMap.isEmpty())
				map.put(pos, node.setScanned().setTerminal());
			else
				map.putAll(newRingMap);
		});	
	}

	private record Node(int ring, boolean scanned, boolean isTerminal) {
		public Node setScanned() {return new Node(this.ring(), true, this.isTerminal());}
		public Node setTerminal() {return new Node(this.ring(), this.scanned(), true);}
		public static Node NONE = new Node(0, false ,false);
	}

	private BlockPos stepShape(BlockPos from, BlockState centerState, boolean isBig) {
		boolean allFalse = true;
		if (level.getBlockState(from).getBlock().equals(centerState.getBlock())) {
			map.put(from, Node.NONE);
			maxBlocks--;
			allFalse = false;
		}
		if (maxBlocks > 0 && level.getBlockState(from.below()).getBlock().equals(centerState.getBlock())) {
			map.put(from.below(), Node.NONE);
			maxBlocks--;
			allFalse = false;
		}	

		if (isBig) {
			if (maxBlocks > 0 && level.getBlockState(from.above()).getBlock().equals(centerState.getBlock())) {
				map.put(from.above(), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, true)).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, true), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, true).above()).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, true).above(), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, true).below()).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, true).below(), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, false)).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, false), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, false).above()).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, false).above(), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
			if (maxBlocks > 0 && level.getBlockState(getAdjacent(from, false).below()).getBlock().equals(centerState.getBlock())) {
				map.put(getAdjacent(from, false).below(), Node.NONE);
				maxBlocks--;
				allFalse = false;
			}
		}
		if (allFalse) return BlockPos.ZERO;
		return from.relative(face);
	}

	private BlockPos getAdjacent(BlockPos pos, boolean left) {
		return switch (face) {
		case NORTH -> {yield left ? pos.west() : pos.east();}
		case SOUTH -> {yield left ? pos.east() : pos.west();}
		case WEST -> {yield left ? pos.south() : pos.north();}
		case EAST -> {yield left ? pos.north() : pos.south();}
		default -> {yield pos;}};
	}
}

